# Pre-build: compresses web/dashboard.html into src/WDashboard.h (PROGMEM, gzip)
Import("env")
import gzip
import os

src = os.path.join(env["PROJECT_DIR"], "web", "dashboard.html")
dst = os.path.join(env["PROJECT_DIR"], "src", "WDashboard.h")

with open(src, "rb") as f:
    data = gzip.compress(f.read(), 9, mtime=0)

lines = []
for i in range(0, len(data), 20):
    lines.append("  " + ", ".join("0x%02x" % b for b in data[i:i + 20]) + ",")
header = (
    "// Generated by scripts/embed_web.py from web/dashboard.html, do not edit\n"
    "#ifndef W_DASHBOARD_H\n#define W_DASHBOARD_H\n\n"
    "const size_t DASHBOARD_HTML_GZ_LEN = %d;\n"
    "const uint8_t DASHBOARD_HTML_GZ[] PROGMEM = {\n%s\n};\n\n#endif\n"
) % (len(data), "\n".join(lines))

old = None
if os.path.exists(dst):
    with open(dst) as f:
        old = f.read()
if old != header:
    with open(dst, "w") as f:
        f.write(header)
    print("WDashboard.h: %d bytes gzip" % len(data))
